Code review identified issues with async signal handlers in src/server.js.

**Current issues:**
1. Using process.on() instead of process.once() - could double-fire
2. Async functions in signal handlers may not complete before exit
3. Hard process.exit(0) doesn't let event loop drain
4. No timeout fallback if server.close() hangs

**Recommended pattern:**
```javascript
let shuttingDown = false;

async function shutdown(server) {
  if (shuttingDown) return;  // Idempotency guard
  shuttingDown = true;

  console.log('Shutting down...');
  try { fs.unlinkSync(WS_ENDPOINT_FILE); } catch {}

  const hardTimeout = setTimeout(() => {
    console.error('Force exiting after timeout');
    process.exit(1);
  }, 5000);

  try {
    await server.close();
    process.exitCode = 0;  // Let event loop drain instead of hard exit
  } finally {
    clearTimeout(hardTimeout);
  }
}

process.once('SIGINT', () => shutdown(server));
process.once('SIGTERM', () => shutdown(server));
process.once('uncaughtException', (e) => { console.error(e); shutdown(server); });
process.once('unhandledRejection', (e) => { console.error(e); shutdown(server); });
```

